from fractions import Fraction as F
rows=[('A',5,(0,0,0,1)),('A',6,(1,0,1,0)),('B',11,(0,0,0,1)),('B',5,(0,1,1,0)),('C',6,(0,1,0,1)),('C',4,(1,0,1,1)),('D',6,(0,0,1,0)),('D',8,(1,1,0,0))]
tests='TUVW'
cost=[F(1),F(1),F(17,10),F(21,10)]
loss=[[0,7,10,21],[7,0,22,11],[19,13,0,19],[12,6,13,0]]
def stop(ids):
    total=sum(rows[i][1] for i in ids)
    return min((sum(F(rows[i][1])*loss[a]['ABCD'.index(rows[i][0])] for i in ids)/total,'ABCD'[a]) for a in range(4))
def best(ids, available, n):
    choices=[stop(ids)]
    if n:
        for t in available:
            choices.append((buy(ids,t,available,n),tests[t]))
    return min(choices)
def buy(ids,t,available,n):
    total=sum(rows[i][1] for i in ids)
    val=cost[t]
    for b in [0,1]:
        subset=[i for i in ids if rows[i][2][t]==b]
        if subset:
            val+=F(sum(rows[i][1] for i in subset),total)*best(subset,[x for x in available if x!=t],n-1)[0]
    return val
ids=list(range(8))
vals={'STOP':stop(ids)[0]}
for t in range(4): vals[tests[t]]=buy(ids,t,list(range(4)),2)
print({k:float(v) for k,v in vals.items()})
first=min(vals,key=vals.get)
print('first',first)
if first!='STOP':
 t=tests.index(first)
 for b in [0,1]:
  subset=[i for i in ids if rows[i][2][t]==b]
  print('branch',b,best(subset,[x for x in range(4) if x!=t],1) if subset else 'IMPOSSIBLE')
print('stop',stop(ids))

